1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <title>Circle Display</title>
7	  <style>
8	    * {
9	      margin: 0;
10	      padding: 0;
11	      box-sizing: border-box;
12	    }
13	    html, body {
14	      width: 100%;
15	      height: 100%;
16	      overflow: hidden;
17	    }
18	    body {
19	      display: flex;
20	      flex-direction: column;
21	      justify-content: center;
22	      align-items: center;
23	      gap: 20px;
24	      background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
25	      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
26	      color: white;
27	      font-size: 14px;
28	      text-align: center;
29	    }
30	    .circle-container {
31	      cursor: pointer;
32	      transition: transform 0.3s ease;
33	      border: none;
34	      background: none;
35	      padding: 0;
36	    }
37	    .circle-container:hover,
38	    .circle-container:focus {
39	      transform: scale(1.08);
40	      outline: none;
41	    }
42	    .circle-container:focus-visible {
43	      outline: 3px solid rgba(255, 255, 255, 0.7);
44	      outline-offset: 12px;
45	      border-radius: 50%;
46	    }
47	    svg {
48	      width: min(400px, 80vw);
49	      height: min(400px, 80vw);
50	      filter: drop-shadow(0 20px 40px rgba(0, 0, 0, 0.3));
51	      display: block;
52	      transition: filter 0.3s ease;
53	    }
54	    circle {
55	      fill: #ffffff;
56	      stroke: rgba(255, 255, 255, 0.2);
57	      stroke-width: 2;
58	      transition: fill 0.3s ease, r 0.3s ease, stroke 0.3s ease;
59	      animation: pulse 3s ease-in-out infinite;
60	    }
61	    .circle-container:hover circle,
62	    .circle-container:focus circle {
63	      fill: #e8f4f8;
64	      r: 205;
65	      stroke: rgba(255, 255, 255, 0.4);
66	    }
67	    .circle-container.active circle {
68	      fill: #ffd700;
69	      animation: pulse-active 0.6s ease-in-out;
70	      stroke: rgba(255, 215, 0, 0.3);
71	    }
72	    .circle-container.active:hover circle {
73	      fill: #ffed4e;
74	    }
75	    .circle-container.active svg {
76	      filter: drop-shadow(0 20px 40px rgba(255, 215, 0, 0.5));
77	    }
78	    .circle-container.color-mode-1 circle {
79	      fill: #ff6b9d;
80	    }
81	    .circle-container.color-mode-1.active svg {
82	      filter: drop-shadow(0 20px 40px rgba(255, 107, 157, 0.5));
83	    }
84	    .circle-container.color-mode-2 circle {
85	      fill: #4ecdc4;
86	    }
87	    .circle-container.color-mode-2.active svg {
88	      filter: drop-shadow(0 20px 40px rgba(78, 205, 196, 0.5));
89	    }
90	    .circle-container.color-mode-3 circle {
91	      fill: #95e1d3;
92	    }
93	    .circle-container.color-mode-3.active svg {
94	      filter: drop-shadow(0 20px 40px rgba(149, 225, 211, 0.5));
95	    }
96	    .hint {
97	      font-size: 12px;
98	      opacity: 0.8;
99	      transition: opacity 0.3s ease;
100	      letter-spacing: 0.5px;
101	    }
102	    .hint.show-shortcuts {
103	      opacity: 1;
104	    }
105	    .circle-container:hover ~ .hint,
106	    .circle-container:focus ~ .hint {
107	      opacity: 1;
108	    }
109	    .mode-indicator {
110	      font-size: 10px;
111	      opacity: 0.6;
112	      margin-top: 8px;
113	      letter-spacing: 1px;
114	      text-transform: uppercase;
115	      transition: opacity 0.3s ease;
116	    }
117	    .mode-indicator.visible {
118	      opacity: 1;
119	    }
120	    @keyframes pulse {
121	      0%, 100% { r: 200; }
122	      50% { r: 202; }
123	    }
124	    @keyframes pulse-active {
125	      0% { r: 200; }
126	      50% { r: 210; }
127	      100% { r: 200; }
128	    }
129	    @keyframes fadeIn {
130	      from { opacity: 0; transform: scale(0.9); }
131	      to { opacity: 1; transform: scale(1); }
132	    }
133	    .circle-container svg {
134	      animation: fadeIn 0.6s ease-out;
135	    }
136	  </style>
137	</head>
138	<body>
139	  <div style="text-align: center;">
140	    <button class="circle-container" id="decorative-circle" aria-label="Interactive circle - click to activate, double-click to change color, press space to toggle or C for color">
141	      <svg viewBox="0 0 400 400" role="presentation">
142	        <circle cx="200" cy="200" r="200"/>
143	      </svg>
144	    </button>
145	    <div class="mode-indicator" id="mode-indicator"></div>
146	  </div>
147	  <div class="hint" id="hint-text">Click to activate • Double-click for color</div>
148	
149	  <script>
150	    const STORAGE_KEY = 'circle-state';
151	    const COLOR_MODES = ['default', 'color-mode-1', 'color-mode-2', 'color-mode-3'];
152	    const COLORS = {
153	      default: 'Default White',
154	      'color-mode-1': 'Pink',
155	      'color-mode-2': 'Teal',
156	      'color-mode-3': 'Mint'
157	    };
158	
159	    const circle = document.getElementById('decorative-circle');
160	    const hint = document.getElementById('hint-text');
161	    const modeIndicator = document.getElementById('mode-indicator');
162	
163	    let state = {
164	      active: false,
165	      colorMode: 0
166	    };
167	
168	    function saveState() {
169	      localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
170	    }
171	
172	    function loadState() {
173	      try {
174	        const saved = localStorage.getItem(STORAGE_KEY);
175	        if (saved) {
176	          state = JSON.parse(saved);
177	          applyState();
178	        }
179	      } catch (e) {
180	        console.warn('Failed to load saved state');
181	      }
182	    }
183	
184	    function applyState() {
185	      circle.classList.remove('active', ...COLOR_MODES);
186	      if (state.active) {
187	        circle.classList.add('active');
188	      }
189	      if (state.colorMode > 0) {
190	        circle.classList.add(COLOR_MODES[state.colorMode]);
191	      }
192	      updateUI();
193	    }
194	
195	    function toggleActive() {
196	      state.active = !state.active;
197	      applyState();
198	      saveState();
199	    }
200	
201	    function cycleColor() {
202	      state.colorMode = (state.colorMode + 1) % COLOR_MODES.length;
203	      state.active = true;
204	      applyState();
205	      saveState();
206	    }
207	
208	    function resetState() {
209	      state = { active: false, colorMode: 0 };
210	      applyState();
211	      saveState();
212	    }
213	
214	    function updateHint() {
215	      if (state.active) {
216	        hint.textContent = 'Active! • Double-click or press C for color • Press R to reset';
217	      } else {
218	        hint.textContent = 'Click to activate • Double-click to change color';
219	      }
220	    }
221	
222	    function updateModeIndicator() {
223	      if (state.active && state.colorMode > 0) {
224	        modeIndicator.textContent = COLORS[COLOR_MODES[state.colorMode]];
225	        modeIndicator.classList.add('visible');
226	      } else {
227	        modeIndicator.classList.remove('visible');
228	      }
229	    }
230	
231	    function updateUI() {
232	      updateHint();
233	      updateModeIndicator();
234	    }
235	
236	    circle.addEventListener('click', toggleActive);
237	
238	    circle.addEventListener('dblclick', (e) => {
239	      e.preventDefault();
240	      cycleColor();
241	    });
242	
243	    circle.addEventListener('keydown', (e) => {
244	      if (e.key === ' ' || e.key === 'Enter') {
245	        e.preventDefault();
246	        toggleActive();
247	      } else if (e.key === 'c' || e.key === 'C') {
248	        e.preventDefault();
249	        cycleColor();
250	      } else if (e.key === 'r' || e.key === 'R') {
251	        e.preventDefault();
252	        resetState();
253	      }
254	    });
255	
256	    circle.addEventListener('mouseenter', () => {
257	      hint.classList.add('show-shortcuts');
258	      if (!state.active) {
259	        hint.textContent = 'Click to activate • Double-click for color • C: color • R: reset';
260	      }
261	    });
262	
263	    circle.addEventListener('mouseleave', () => {
264	      hint.classList.remove('show-shortcuts');
265	      updateHint();
266	    });
267	
268	    loadState();
269	    circle.focus();
270	  </script>
271	</body>
272	</html>
